#!/bin/sh
# Generate the index of the public functions of the lib (Markdown).
# The description of each function is taken from the comment block just above it.
# Usage: ./release/gen_index.sh [output_file]   (default: stdout)

root=$(cd "$(dirname "$0")/.." && pwd)
output="$1"

generate() {
    cat <<'HEADER'
# posix_shell_lib - function index

<!-- generated by release/gen_index.sh - do not edit by hand (run `make docs`) -->

After installation, every function is prefixed by a namespace built from its file path:
`posixshell_<folder>_<file>__<function>`, e.g. `set_json_value` in `io/files/json.sh`
becomes `posixshell_io_files_json__set_json_value`.
Read the comment block above the function in `src/<file>` for arguments, return codes and examples.

HEADER
    cd "$root/src" || exit 1
    for file in $(find . -name '*.sh' | sed 's|^\./||' | sort); do
        case "$file" in
            */*) namespace="posixshell_$(dirname "$file" | tr '/' '_')_$(basename "${file%.sh}")" ;;
            *) namespace="posixshell_${file%.sh}" ;;
        esac
        printf '## %s\n\n' "$file"
        awk -v ns="$namespace" '
            function flush(name,    i, d, in_desc) {
                d = ""; in_desc = 0
                for (i = 1; i <= n; i++) {
                    if (buf[i] ~ /^Description:/) { in_desc = 1; continue }
                    if (in_desc) {
                        if (buf[i] == "") break
                        d = d (d == "" ? "" : " ") buf[i]
                    }
                }
                if (d == "") {
                    for (i = 1; i <= n; i++) {
                        if (buf[i] == "" || buf[i] ~ /^(#+|Function:.*|USAGE:|EXAMPLES:)$/) continue
                        d = buf[i]; break
                    }
                }
                if (d == "") d = "(no description)"
                printf "- `%s__%s` (`%s`) - %s\n", ns, name, name, d
            }
            /^#/ {
                line = $0; sub(/^# ?/, "", line); gsub(/^[ \t]+|[ \t]+$/, "", line)
                buf[++n] = line; next
            }
            /^[ \t]*$/ { next }
            /^[a-zA-Z][a-zA-Z0-9_]*\(\) *\{/ {
                name = $1; sub(/\(\).*/, "", name)
                flush(name); n = 0; next
            }
            { n = 0 }
        ' "$file"
        printf '\n'
    done
}

if [ -n "$output" ]; then
    generate > "$output"
else
    generate
fi
